struct M { a: u32, b: u32, c: u32, d: u32, e: u32 }
@group(0) @binding(0) var<storage> input: array<u32>;
const WG_SIZE = 256u;
fn combine(x: M, y: M) -> M { return M(x.a + y.a, x.b + y.b, x.c + y.c, x.d + y.d, x.e + y.e); }
@group(0) @binding(1) var<storage, read_write> reduced: array<u32>;
var<workgroup> sh: array<M, WG_SIZE>;
@compute @workgroup_size(256)
fn main(@builtin(global_invocation_id) gid: vec3<u32>, @builtin(local_invocation_id) lid: vec3<u32>) {
    let w = input[gid.x];
    var agg = M(w & 1u, (w >> 1u) & 1u, (w >> 2u) & 1u, (w >> 3u) & 1u, (w >> 4u) & 1u);
    sh[lid.x] = agg;
    for (var i = 0u; i < firstTrailingBit(WG_SIZE); i += 1u) {
        workgroupBarrier();
        if lid.x + (1u << i) < WG_SIZE {
            let other = sh[lid.x + (1u << i)];
            agg = combine(agg, other);
        }
        workgroupBarrier();
        sh[lid.x] = agg;
    }
    if lid.x == 0u { reduced[gid.x >> 8u] = agg.a + agg.b + agg.c + agg.d + agg.e; }
}

